import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {mkdtempSync,readFileSync,writeFileSync,mkdirSync,rmSync,symlinkSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {expectedFromEnvironment,expectedFromOfficialOrigin,stageArtifact,inputsSHA256,officialMetadata,validateArtifactMetadata,verifyProof,verifyArtifact,safeRelative} from './pr356-artifacts.mjs';
const sha=value=>createHash('sha256').update(value).digest('hex');
const times={started_at:'2026-10-26T00:00:00Z',created_at:'2026-10-26T00:01:00Z',completed_at:'2026-10-26T00:02:00Z'};
function fixture({role='schema-upgrade',zipEntries}={}){
 const root=mkdtempSync(join(tmpdir(),'pr356-artifact-control-')),directory=join(root,'download');
 const inputs={schemaVersion:1,files:[{path:'fixture.txt',mode:'100644',blob:'b'.repeat(40)}],configuration:{phase:role},tools:{node:'24.21.0'},dependencies:{lock:'c'.repeat(40)}};
 const phase=role==='frontend-dist'?'frontend-image':role,spec={id:phase,jobName:'PR356 / '+phase,caseIds:['fixture-check'],inputs,inputsSHA256:inputsSHA256(inputs)};
 const source={repository:'caohuibj/eduK12-new-version',runId:'123',head:'a'.repeat(40),producerAttempt:1};
 const rawFiles={'step.log':'fixture command completed\n','facts.json':'{"synthetic":true}\n'};
 const files=Object.fromEntries(Object.entries(rawFiles).map(([p,raw])=>[p,{sha256:sha(raw),bytes:Buffer.byteLength(raw)}]));
 const proof={schemaVersion:1,kind:'pr356-phase-proof',phaseId:phase,status:'success',source,inputs,inputsSHA256:spec.inputsSHA256,
  command:{argv:['stub-control-command'],cwd:'/synthetic',exitCode:0,logSHA256:sha(rawFiles['step.log']),startedAt:times.started_at,completedAt:times.completed_at},checks:[{id:'fixture-check',status:'passed'}],outputs:{files}};
 const entries=zipEntries??{...rawFiles,'phase-receipt.json':JSON.stringify(proof)};
 const json=join(root,'entries.json'),zip=join(root,'source.zip');writeFileSync(json,JSON.stringify(entries));
 execFileSync('python3',['-c',"import json,sys,zipfile\nwith zipfile.ZipFile(sys.argv[2],'w',zipfile.ZIP_DEFLATED) as z:\n for name,value in json.load(open(sys.argv[1])).items():z.writestr(name,value)",json,zip],{stdio:['ignore','pipe','pipe']});
 const bytes=readFileSync(zip),env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:source.repository,GITHUB_RUN_ID:'123',GITHUB_SHA:source.head,GITHUB_RUN_ATTEMPT:'2',PR356_PRODUCER_RUN:'123',PR356_PRODUCER_HEAD:source.head,PR356_PRODUCER_ATTEMPT:'1',PR356_ARTIFACT_ID:'456',PR356_ARTIFACT_NAME:`pr356-${role}-123-1`,PR356_ARTIFACT_DIGEST:'sha256:'+sha(bytes)};
 const expected=expectedFromEnvironment(role,spec,env),meta={id:456,name:env.PR356_ARTIFACT_NAME,expired:false,size_in_bytes:bytes.length,digest:env.PR356_ARTIFACT_DIGEST,created_at:times.created_at,expires_at:'2099-01-01T00:00:00Z',workflow_run:{id:123,head_sha:source.head}};
 const job={id:789,name:spec.jobName,status:'completed',conclusion:'success',head_sha:source.head,run_id:123,run_attempt:1,started_at:times.started_at,completed_at:times.completed_at};
 const requests=[];let metadataChange=x=>x,jobsChange=x=>x,runChange=x=>x,apiStatus=200;
 const fetcher=async(url,options={})=>{
  requests.push({url:String(url),options});const u=new URL(url);
  if(u.hostname.endsWith('.blob.core.windows.net')){assert.equal(options.headers,undefined,'Bearer must never reach blob storage');return new Response(bytes,{status:200});}
  assert.equal(u.origin,'https://api.github.com');assert.equal(options.headers.Authorization,'Bearer stub-api-token');
  if(u.pathname.endsWith('/zip'))return new Response(null,{status:302,headers:{location:'https://productionresults.blob.core.windows.net/synthetic'}});
  if(apiStatus!==200)return new Response('{}',{status:apiStatus});
  if(u.pathname.endsWith('/artifacts/456'))return Response.json(metadataChange(structuredClone(meta)));
  if(u.pathname.endsWith('/attempts/1'))return Response.json(runChange({id:123,head_sha:source.head,run_attempt:1,path:'.github/workflows/ci.yml'}));
  if(u.pathname.endsWith('/jobs'))return Response.json({jobs:jobsChange([structuredClone(job)])});
  throw new Error('Unexpected API route');
 };
 return {root,directory,bytes,proof,spec,expected,env,meta,job,requests,fetcher,entries,mutateMetadata:fn=>metadataChange=fn,mutateJobs:fn=>jobsChange=fn,mutateRun:fn=>runChange=fn,apiStatus:value=>apiStatus=value,clean:()=>rmSync(root,{recursive:true,force:true})};
}
test('downloads the successful producer attempt once and repeatedly verifies the same official ZIP and local bytes',async()=>{
 const f=fixture();try{
  const first=await verifyArtifact({expected:f.expected,directory:f.directory,mode:'download',token:'stub-api-token',fetcher:f.fetcher});assert.equal(first.source.producerAttempt,1);assert.equal(first.producerJob.attempt,1);assert.equal(first.proofPath,join(f.directory,'phase-receipt.json'));
  const second=await verifyArtifact({expected:f.expected,directory:f.directory,mode:'verify-local',token:'stub-api-token',fetcher:f.fetcher});assert.equal(second.zipSHA256,first.zipSHA256);assert.equal(f.requests.filter(r=>r.url.endsWith('/zip')).length,1);assert(!f.requests.some(r=>r.url.includes('/attempts/2')));
 }finally{f.clean();}
});
for(const [name,change]of Object.entries({missingID:e=>delete e.PR356_ARTIFACT_ID,missingDigest:e=>delete e.PR356_ARTIFACT_DIGEST,crossRun:e=>e.PR356_PRODUCER_RUN='99',crossHead:e=>e.PR356_PRODUCER_HEAD='c'.repeat(40),futureAttempt:e=>e.PR356_PRODUCER_ATTEMPT='3',consumerAttemptName:e=>e.PR356_ARTIFACT_NAME='pr356-schema-upgrade-123-2'}))test('rejects '+name+' without fallback',()=>{const f=fixture();try{const env={...f.env};change(env);assert.throws(()=>expectedFromEnvironment('schema-upgrade',f.spec,env));}finally{f.clean();}});
for(const [name,change]of Object.entries({expired:m=>m.expired=true,expiredDate:m=>m.expires_at='2000-01-01T00:00:00Z',wrongID:m=>m.id=457,wrongName:m=>m.name+='-other',wrongHead:m=>m.workflow_run.head_sha='c'.repeat(40),wrongRun:m=>m.workflow_run.id=99,wrongDigest:m=>m.digest='sha256:'+'0'.repeat(64),missingDigest:m=>delete m.digest,wrongAttemptTime:m=>m.created_at='2026-10-27T00:00:00Z'}))test('rejects official artifact '+name,async()=>{const f=fixture();try{f.mutateMetadata(m=>{change(m);return m;});await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher));assert(!f.requests.some(r=>r.url.endsWith('/zip')));}finally{f.clean();}});
for(const status of [403,404])test('stops at official metadata HTTP '+status,async()=>{const f=fixture();try{f.apiStatus(status);await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher),/no fallback/);assert.equal(f.requests.length,1);}finally{f.clean();}});
test('rejects missing or failed producer jobs and wrong original run attempt',async()=>{const f=fixture();try{f.mutateJobs(()=>[]);await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher),/missing/);f.mutateJobs(j=>[{...j[0],conclusion:'failure'}]);await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher),/successful/);f.mutateJobs(x=>x);f.mutateRun(r=>({...r,run_attempt:2}));await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher));}finally{f.clean();}});
for(const [name,change]of Object.entries({inputDrift:p=>p.inputs.dependencies.lock='0'.repeat(40),missingChecks:p=>p.checks=[],failedCommand:p=>p.command.exitCode=1,wrongProducerAttempt:p=>p.source.producerAttempt=2,missingLog:p=>p.command.logSHA256='0'.repeat(64),extraChecks:p=>p.checks.push({id:'extra',status:'passed'})}))test('rejects proof '+name,()=>{const f=fixture();try{const p=structuredClone(f.proof);change(p);assert.throws(()=>verifyProof(p,f.expected));}finally{f.clean();}});
for(const mutation of ['changed','extra','symlink','zip','proof-and-payload'])test('local verification rejects '+mutation+' bytes without another download',async()=>{const f=fixture();try{await verifyArtifact({expected:f.expected,directory:f.directory,mode:'download',token:'stub-api-token',fetcher:f.fetcher});if(mutation==='changed')writeFileSync(join(f.directory,'facts.json'),'different');if(mutation==='extra')writeFileSync(join(f.directory,'extra.txt'),'extra');if(mutation==='symlink'){rmSync(join(f.directory,'facts.json'));symlinkSync(join(f.directory,'step.log'),join(f.directory,'facts.json'));}if(mutation==='zip')writeFileSync(f.directory+'.artifact.zip','tampered');if(mutation==='proof-and-payload'){const raw='tampered facts';writeFileSync(join(f.directory,'facts.json'),raw);const proof=JSON.parse(readFileSync(join(f.directory,'phase-receipt.json')));proof.outputs.files['facts.json']={sha256:sha(raw),bytes:Buffer.byteLength(raw)};writeFileSync(join(f.directory,'phase-receipt.json'),JSON.stringify(proof));}await assert.rejects(verifyArtifact({expected:f.expected,directory:f.directory,mode:'verify-local',token:'stub-api-token',fetcher:f.fetcher}));assert.equal(f.requests.filter(r=>r.url.endsWith('/zip')).length,1);}finally{f.clean();}});
for(const path of ['../escape','/absolute','a/../escape','a\\escape'])test('safe extraction refuses '+path,async()=>{const f=fixture({zipEntries:{[path]:'untrusted'}});try{await assert.rejects(verifyArtifact({expected:f.expected,directory:f.directory,mode:'download',token:'stub-api-token',fetcher:f.fetcher}));}finally{f.clean();}});
test('manifest traversal and missing complete config/tools/dependency inputs are refused',()=>{const f=fixture();try{const p=structuredClone(f.proof);p.outputs.files['../escape']={sha256:sha('x'),bytes:1};assert.throws(()=>verifyProof(p,f.expected));for(const key of ['configuration','tools','dependencies']){const spec=structuredClone(f.spec);spec.inputs[key]={};spec.inputsSHA256=inputsSHA256(spec.inputs);assert.throws(()=>expectedFromEnvironment('schema-upgrade',spec,f.env));}}finally{f.clean();}});


test('numeric-string producer IDs from the DB phase keep the same strict original identity',()=>{const f=fixture();try{const p=structuredClone(f.proof);p.source.runId=123;p.source.producerAttempt='1';assert.deepEqual(verifyProof(p,f.expected),p.outputs.files);p.source.producerAttempt='2';assert.throws(()=>verifyProof(p,f.expected));}finally{f.clean();}});
test('official timestamp precision permits only the remainder of the recorded completion second',async()=>{const f=fixture();try{f.mutateMetadata(m=>({...m,created_at:'2026-10-26T00:02:00.999Z'}));await officialMetadata(f.expected,'stub-api-token',f.fetcher);f.mutateMetadata(m=>({...m,created_at:'2026-10-26T00:02:01.000Z'}));await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher),/not created/);f.mutateJobs(j=>[{...j[0],completed_at:'2026-10-26T00:02:00.123Z'}]);f.mutateMetadata(m=>({...m,created_at:'2026-10-26T00:02:00.124Z'}));await assert.rejects(officialMetadata(f.expected,'stub-api-token',f.fetcher),/not created/);}finally{f.clean();}});
test('explicit aggregate evidence origins pin every original identity without enabling default cross-run reuse',async()=>{const f=fixture();try{const origin={kind:'pr356-explicit-official-origin',runId:'123',sourceHead:f.expected.head,producerAttempt:1,jobId:789,artifactId:456,artifactName:f.meta.name,artifactDigest:f.meta.digest};const e=expectedFromOfficialOrigin('schema-upgrade',f.spec,origin);assert.equal(e.originKind,'explicit-official-evidence-read');assert.equal(e.qualificationClaim,false);await officialMetadata(e,'stub-api-token',f.fetcher);await assert.rejects(officialMetadata({...e,producerJobId:790},'stub-api-token',f.fetcher),/job ID/);assert.throws(()=>expectedFromOfficialOrigin('schema-upgrade',f.spec,{...origin,jobId:undefined}));assert.throws(()=>expectedFromEnvironment('schema-upgrade',f.spec,{...f.env,GITHUB_RUN_ID:'999'}));}finally{f.clean();}});


function producerDirectory(f,entries=f.entries){mkdirSync(f.directory);for(const [path,raw]of Object.entries(entries)){const target=join(f.directory,path);mkdirSync(join(target,'..'),{recursive:true});writeFileSync(target,raw);}return {...f.env,GITHUB_RUN_ATTEMPT:'1',RUNNER_TEMP:f.root};}
test('producer stage copies exact original bytes without artifact IDs, token, API or qualification',async()=>{const f=fixture();try{const env=producerDirectory(f);for(const key of Object.keys(env))if(key.startsWith('PR356_'))delete env[key];const original=readFileSync(join(f.directory,'phase-receipt.json'));const destination=join(f.root,'upload');const r=await stageArtifact({role:'schema-upgrade',spec:f.spec,directory:f.directory,destination,env,readHead:()=>f.expected.head});assert.equal(r.qualificationClaim,false);assert.equal(r.kind,'pr356-local-artifact-stage');assert.deepEqual(readFileSync(join(destination,'phase-receipt.json')),original);assert.deepEqual(readFileSync(join(destination,'facts.json')),readFileSync(join(f.directory,'facts.json')));assert.equal(f.requests.length,0);await assert.rejects(stageArtifact({role:'schema-upgrade',spec:f.spec,directory:f.directory,destination,env,readHead:()=>f.expected.head}),/must be new/);}finally{f.clean();}});
test('producer stage separates frontend dist from the image-role bytes with the same original proof',async()=>{const f=fixture({role:'frontend-dist'});try{const html='<p>dist only</p>',manifest=JSON.stringify({head:f.expected.head,run:'123',attempt:1,files:{'index.html':{sha256:sha(html),bytes:Buffer.byteLength(html)}}});const proof=structuredClone(f.proof);proof.outputs={artifactFiles:{'frontend-image':proof.outputs.files,'frontend-dist':{'dist/index.html':{sha256:sha(html),bytes:Buffer.byteLength(html)},'frontend-dist.json':{sha256:sha(manifest),bytes:Buffer.byteLength(manifest)}}}};const entries={...f.entries,'phase-receipt.json':JSON.stringify(proof),'dist/index.html':html,'frontend-dist.json':manifest};const env=producerDirectory(f,entries),destination=join(f.root,'dist-upload');const r=await stageArtifact({role:'frontend-dist',spec:f.spec,directory:f.directory,destination,env,readHead:()=>f.expected.head});assert.deepEqual(Object.keys(r.payloadFiles).sort(),['dist/index.html','frontend-dist.json']);assert.throws(()=>readFileSync(join(destination,'facts.json')));assert.deepEqual(readFileSync(join(destination,'phase-receipt.json')),readFileSync(join(f.directory,'phase-receipt.json')));}finally{f.clean();}});
test('producer stage rejects wrong current attempt, payload drift and destinations outside RUNNER_TEMP',async()=>{const f=fixture();try{const env=producerDirectory(f),args={role:'schema-upgrade',spec:f.spec,directory:f.directory,destination:join(f.root,'upload'),env,readHead:()=>f.expected.head};await assert.rejects(stageArtifact({...args,env:{...env,GITHUB_RUN_ATTEMPT:'2'}}));await assert.rejects(stageArtifact({...args,destination:join(f.root,'..','outside-stage')}),/RUNNER_TEMP/);writeFileSync(join(f.directory,'facts.json'),'tampered');await assert.rejects(stageArtifact(args));}finally{f.clean();}});
